// A: i x j
// s: j
// q: i
// p: j
// r: i
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// -----------------------------------------------------------------
	// Phase 1: initialize s[j] = 0 for all j.
	// (q[i] is initialized implicitly inside the main loop in registers.)
	// -----------------------------------------------------------------
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// Cache the problem sizes once (not used directly for iteration,
	// which is driven by the traverser, but useful for documentation
	// and potential assertions).
	const std::size_t n = A | get_length<'i'>(); // number of rows
	const std::size_t m = A | get_length<'j'>(); // number of columns
	(void)n;
	(void)m;

	// -----------------------------------------------------------------
	// Phase 2: main BiCG kernel
	//
	// For each row i:
	//   q[i] = 0;
	//   for each column j:
	//     s[j] += r[i] * A[i][j];
	//     q[i] += A[i][j] * p[j];
	//
	// Implementation details:
	//  * Outer dimension is 'i' to follow the row‑major layout of A.
	//  * r[i] is hoisted outside the inner loop (fewer loads).
	//  * q[i] is accumulated in a register and written once per row,
	//    reducing memory traffic and improving vectorization potential.
	// -----------------------------------------------------------------
	traverser(A, s, q, p, r).template for_dims<'i'>([&](auto inner_trav) {
		// State with the current row index 'i' fixed.
		auto istate = inner_trav.state();

		// Hoist r[i] and the accumulator for q[i] into registers.
		const num_t ri = r[istate];
		num_t qi = SCALAR_VAL(0.0);

		// Iterate over the remaining dimension 'j' for this fixed 'i'.
		inner_trav.for_each([&](auto state) {
			// state contains both 'i' and 'j' and can be used for all bags.
			const num_t Aij = A[state];
			const num_t pj  = p[state];

			// s[j] += r[i] * A[i][j];
			s[state] += ri * Aij;

			// q[i] += A[i][j] * p[j];
			qi += Aij * pj;
		});

		// Store the accumulated value of q[i] exactly once.
		q[istate] = qi;
	});
	#pragma endscop
