// Main computational kernel implementation with j-blocking.
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// J_BLOCK is a compile-time tuning parameter controlling the tile size
// along the j-dimension. The traversal order in j is preserved
// (0..M-1), it is only grouped into contiguous blocks to improve
// cache locality and enable better vectorization opportunities.
template<std::size_t J_BLOCK, class ABag, class SBag, class QBag, class PBag, class RBag>
void kernel_bicg_impl(ABag A, SBag s, QBag q, PBag p, RBag r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([=](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// Length in 'j' used for blocking
	const std::size_t m = s | get_length<'j'>();

	// For each i:
	//   q[i] = 0;
	//   for each j (blocked):
	//     s[j] += r[i] * A[i][j];
	//     q[i] += A[i][j] * p[j];
	//
	// The outer i-loop is expressed via for_dims<'i'>.
	traverser(A, s, q, p, r).template for_dims<'i'>([=](auto inner) {
		// State with current i fixed
		auto istate = inner.state();

		// r[i] is constant within this i-row; load once
		const num_t r_i = r[istate];

		// Accumulate q[i] in a register and store once per i.
		num_t q_acc = SCALAR_VAL(0.0);

		// Blocked traversal over the j-dimension using slices.
		// This preserves the j-iteration order (0..m-1) but groups
		// accesses into contiguous blocks to improve cache behavior.
		for (std::size_t jb = 0; jb < m; jb += J_BLOCK) {
			const std::size_t block_len =
				(jb + J_BLOCK <= m) ? J_BLOCK : (m - jb);

			// Restrict inner traverser to the current j-block:
			// j in [jb, jb + block_len)
			auto block_trav = inner.order(noarr::slice<'j'>(jb, block_len));

			// Iterate over all (i, j) in this block.
			block_trav.for_each([&](auto state) {
				// state has 'i' and 'j'; it can be used directly with all bags.

				const num_t A_ij = A[state];
				const num_t p_j  = p[state];

				// s[j] += r[i] * A[i][j];
				s[state] += r_i * A_ij;

				// q[i] partial accumulation
				q_acc += A_ij * p_j;
			});
		}

		// Finalize q[i] once per i (instead of updating q[i] in every j step).
		q[istate] = q_acc;
	});
	#pragma endscop
}

