	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// A: i x j
// r: i
// p: j
// -----------------------------------------------------------------------------
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Pre-compute lengths once; they are loop-invariant.
	const std::size_t m = p | get_length<'j'>();
	const std::size_t n = r | get_length<'i'>();

	// p[j] = (j % m) / m;
	traverser(p).for_each([&](auto state) {
		const auto j = get_index<'j'>(state);
		p[state] = (num_t)(j % m) / (num_t)m;
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([&](auto state) {
		const auto i = get_index<'i'>(state);
		r[state] = (num_t)(i % n) / (num_t)n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// Note: we reuse 'n' as the length in 'i'.
	traverser(A).for_each([&](auto state) {
		const auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)(i * (j + 1) % n) / (num_t)n;
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// We implement the BiCG kernel:
//
//   s[j] = 0
//   for i:
//     q[i] = 0
//     for j:
//       s[j] += r[i] * A[i][j];
//       q[i] += A[i][j] * p[j];
//
// Optimization notes:
//  - We zero s in a separate pass (as in the original).
//  - We tile the 'j' dimension using into_blocks_dynamic<'j','J','j','b'>
//    inside the traversal over A, s and p. The new synthetic dimensions
//    'J' (block index) and 'b' (presence flag) are only used to control
//    traversal order; the states seen in the kernel body still carry the
//    original 'i' and 'j' indices.
//  - For each i we:
//      * read r[i] once into a scalar r_i,
//      * accumulate q[i] into a scalar q_i, and
//      * write q[i] back once after all j have been processed.
//    This reduces repeated address computation for q[i].
// -----------------------------------------------------------------------------

template<std::size_t J_BLOCK>
[[gnu::flatten, gnu::noinline]]
void kernel_bicg_impl(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// -------------------------------------------------------------------------
	// 1) Initialize s[j] = 0 for all j
	// -------------------------------------------------------------------------
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// -------------------------------------------------------------------------
	// 2) Main BiCG computation
	//
	//    We drive the traversal by A, s and p, because all three share the
	//    {i, j} dimensions. The q and r vectors depend only on 'i', so we
	//    access them explicitly via the 'i' index obtained from the traverser.
	//
	//    To improve data locality in A, s and p along the 'j' dimension and to
	//    enable better cache utilization and vectorization, we apply a blocking
	//    transformation to 'j':
	//
	//      into_blocks_dynamic<'j', 'J', 'j', 'b'>(J_BLOCK)
	//
	//    - 'j'      : original dimension to be split
	//    - 'J'      : block index (major part of j)
	//    - 'j'      : index within a block (minor part, we reuse the name)
	//    - 'b'      : a helper dimension that is empty for out-of-range
	//                 elements of the last block and unit for valid elements
	//
	//    Using .order(...) ensures the *physical* layout is unchanged; only
	//    the traversal order is modified. States passed to the lambda still
	//    contain just 'i' and 'j', so indexing A, s, p, q, r works exactly
	//    as before.
	// -------------------------------------------------------------------------

	auto blocked_trav = traverser(A, s, p).order(
		noarr::into_blocks_dynamic<'j', 'J', 'j', 'b'>(noarr::lit<J_BLOCK>)
	);

	// Outer loop over i (rows of A, and indices of q and r)
	blocked_trav.template for_dims<'i'>([&](auto trav_i) {
		// trav_i.state() contains the current 'i' index (original dimension).
		auto istate = trav_i.state();

		// Load r[i] once per row
		const num_t r_i = r[istate];

		// Accumulator for q[i]
		num_t q_i = SCALAR_VAL(0.0);

		// Middle loop over 'J' = blocks of the 'j' dimension.
		// The body still sees states with 'i' and 'j'; 'J' and 'b' are
		// used internally by the traverser to control which (i, j) pairs
		// are visited and in which order.
		trav_i.template for_dims<'J'>([&](auto trav_iJ) {
			// Inner loop over j within the current block
			trav_iJ.for_each([&](auto state) {
				// state has original indices 'i' and 'j'
				const num_t a_ij = A[state];

				// s[j] += r[i] * A[i][j];
				s[state] += r_i * a_ij;

				// q[i] += A[i][j] * p[j];
				q_i += a_ij * p[state];
			});
		});

		// Store the accumulated q[i] once per row.
		q[istate] = q_i;
	});
	#pragma endscop
}

[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	// Dispatch to the implementation with a compile-time block size so that
	// the blocking transformation can be fully optimized.
	kernel_bicg_impl<BICG_BLOCK_J>(A, s, q, p, r);
}

