using namespace noarr;

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

/**
 * Tuning knobs and layout description.
 *
 * The rest of the code is written in a layout-agnostic way using Noarr
 * dimensions ('i' for rows, 'j' for columns), so changing these constants
 * does not change correctness, only performance characteristics.
 */
struct tuning {
	// Select whether A is stored row-major (default) or column-major.
	// Row-major: 'j' is the inner/fast dimension.
	static constexpr bool a_row_major = true;

	// Example knob for cache- or vector-width–compatible blocking.
	// Currently not used directly inside the kernel, but kept here so that
	// future kernels can easily use a consistent block size.
	static constexpr std::size_t j_block_elems = 64;

	// Helper to build A's layout proto-structure based on a_row_major.
	static constexpr auto make_a_layout() {
		if constexpr (a_row_major) {
			// A: i x j (row-major: j is the inner/fast dimension)
			return j_vec ^ i_vec;
		} else {
			// Alternative: column-major (i is the inner/fast dimension)
			return i_vec ^ j_vec;
		}
	}

	// 2D matrix layout for A
	DEFINE_PROTO_STRUCT(a_layout, make_a_layout());

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

/**
 * Array initialization
 *
 * A: i x j
 * r: i
 * p: j
 *
 * The loops are expressed via Noarr traversers. Some arithmetic is
 * simplified and common sub-expressions are hoisted out of the loops
 * to reduce work per element.
 */
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Query lengths once – they are invariant across the traversals.
	const std::size_t m = p | get_length<'j'>(); // length in 'j'
	const std::size_t n = r | get_length<'i'>(); // length in 'i'

	// Precompute reciprocals to turn divisions into multiplications.
	const num_t inv_m = SCALAR_VAL(1.0) / static_cast<num_t>(m);
	const num_t inv_n = SCALAR_VAL(1.0) / static_cast<num_t>(n);

	// p[j] = (j % m) / m;
	// Since 0 <= j < m, (j % m) == j, so we can drop the modulo.
	traverser(p).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j) * inv_m;
	});

	// r[i] = (i % n) / n;
	// Similarly, 0 <= i < n => (i % n) == i.
	traverser(r).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i) * inv_n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// We keep the modulo (needed for correctness), but replace the divide
	// by a multiplication with inv_n.
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const std::size_t val = (static_cast<std::size_t>(i) *
		                         (static_cast<std::size_t>(j) + 1u)) % n;
		A[state] = static_cast<num_t>(val) * inv_n;
	});
}

/**
 * Main computational kernel
 *
 * A: i x j
 * s: j
 * q: i
 * p: j
 * r: i
 *
 * Original algorithm:
 *   s[j] = 0
 *   For each i:
 *     q[i] = 0;
 *     For each j:
 *       s[j] += r[i] * A[i][j];
 *       q[i] += A[i][j] * p[j];
 *
 * Optimizations:
 *  - q is zeroed in a separate pass, which makes the double sum purely
 *    accumulative and easier to reason about.
 *  - For each i, q[i] is accumulated entirely in a scalar register (q_i)
 *    inside the inner j-loop and written back once per i. This avoids
 *    repeated loads/stores of q[i] and gives the compiler a clear reduction
 *    pattern that is easy to vectorize over 'j'.
 *  - All loops remain expressed via Noarr traversers/for_dims, so the
 *    layout can still be changed by tuning::a_layout without touching
 *    the kernel logic.
 */
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// q[i] = 0 for all i
	traverser(q).for_each([&](auto state) {
		q[state] = SCALAR_VAL(0.0);
	});

	// For each i:
	//   for each j:
	//     s[j] += r[i] * A[i][j];
	//     q[i] += A[i][j] * p[j];
	//
	// We keep 'i' as the explicit outer dimension via for_dims<'i'>.
	traverser(A, s, q, p, r).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed (no 'j' yet).
		auto istate = inner.state();

		// r[i] and q[i] live in registers for the whole inner loop.
		const num_t r_i = r[istate];
		num_t q_i = SCALAR_VAL(0.0); // q[i] is already zeroed above

		// Loop over all j for the current i.
		inner.for_each([&](auto state) {
			// state has 'i' and 'j'
			const num_t a_ij = A[state];
			const num_t p_j  = p[state];

			// s[j] += r[i] * A[i][j];
			s[state] += r_i * a_ij;

			// Accumulate contribution to q[i] in a scalar register.
			q_i += a_ij * p_j;
		});

		// Write back the accumulated q[i] once per i.
		q[istate] = q_i;
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N; // length in 'i'
	std::size_t m = M; // length in 'j'

	// Common length proto-structure
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(m);

	// Allocate bags with chosen layouts
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto s = noarr::bag(noarr::scalar<num_t>() ^ tuning.s_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);

	// Initialize arrays
	init_array(A.get_ref(), r.get_ref(), p.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_bicg(A.get_ref(), s.get_ref(), q.get_ref(), p.get_ref(), r.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print live-out data to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, s.get_ref());
		noarr::serialize_data(std::cerr, q.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
