	// Use for_dims<'i'> to expose the natural row structure:
	//   outer dimension 'i', inner dimension 'j'.
	traverser(A).template for_dims<'i'>([&](auto inner) {
		auto istate = inner.state(); // contains only 'i'
		const std::size_t i = get_index<'i'>(istate);

		inner.for_each([&](auto state) {
			const std::size_t j = get_index<'j'>(state);
			A[state] = static_cast<num_t>((i * (j + 1)) % n) / static_cast<num_t>(n);
		});
