// -----------------------------------------------------------------------------
// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// We keep the mathematical structure identical to:
//
//   s[j] = 0;
//   for i:
//     q[i] = 0;
//     for j:
//       s[j] += r[i] * A[i][j];
//       q[i] += A[i][j] * p[j];
//
// but:
//   * Zero q[i] in a separate traversal before the main nest.
//   * Keep r[i] and q[i] in registers for the entire inner j-loop.
//   * Use noarr::traverser with for_dims<'i'> for a clear row-major traversal.
//   * All traversals use Noarr abstractions, no raw index arithmetic.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// q[i] = 0 for all i
	// Pulling this out of the (i, j) loop allows us to keep q[i]
	// purely in a register within the inner kernel.
	traverser(q).for_each([&](auto state) {
		q[state] = SCALAR_VAL(0.0);
	});

	// For each row i:
	//   take r[i] into a register;
	//   accumulate q[i] in a register across all j;
	//   update s[j] and q[i] using A[i][j] and p[j].
	//
	// We traverse A, s, q, p, r together so that all bags see the same
	// (i, j) index_state. Bags that do not have a particular dimension
	// (e.g. q, r lack 'j') simply ignore it.
	traverser(A, s, q, p, r).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed (only 'i' present here)
		auto istate = inner.state();

		// Load r[i] once per row and keep it in a register
		const num_t r_i = r[istate];

		// Local accumulator for q[i]; start from q[i] (currently 0)
		num_t q_i = q[istate];

		// Loop over all j for this fixed i. Traverser guarantees that 'j'
		// is the remaining dimension and will be iterated in a cache-friendly
		// order for the chosen A layout (row-major: j is contiguous).
		inner.for_each([&](auto state) {
			// state has dimensions 'i' and 'j'.
			const num_t a_ij = A[state]; // A[i][j]
			const num_t p_j  = p[state]; // p[j]

			// s[j] += r[i] * A[i][j];
			s[state] += r_i * a_ij;

			// Accumulate q[i] in a register:
			// we do not update q[] in memory inside the j-loop.
			q_i += a_ij * p_j;
		});

		// After finishing the inner j-loop, write back q[i] once.
		q[istate] = q_i;
	});
	#pragma endscop
